def load() -> pd.DataFrame:
    import pandas as pd, glob, os
    paths = glob.glob('data/legal/input/csn-data-book-2024-csv/CSVs/State MSA Identity Theft data/*.csv')
    rows = []
    for p in sorted(paths)[:3]:
        try:
            df = pd.read_csv(p)
        except Exception:
            df = pd.read_csv(p, encoding='latin-1')
        rows.append({
            'path': p,
            'nrows': len(df),
            'ncols': df.shape[1],
            'columns': list(df.columns)[:20],
            'head': df.head(2).to_json(orient='records')
        })
    return pd.DataFrame(rows)

def load() -> pd.DataFrame:
    import pandas as pd, glob, os
    paths = sorted(glob.glob('data/legal/input/csn-data-book-2024-csv/CSVs/State MSA Fraud and Other data/*.csv'))
    rows = []
    for p in paths[:3]:
        df = pd.read_csv(p)
        rows.append({
            'path': p,
            'nrows': len(df),
            'ncols': df.shape[1],
            'columns': list(df.columns),
            'head': df.head(3).to_dict(orient='records')
        })
    return pd.DataFrame(rows)
